CREATE OR REPLACE FUNCTION public.save_sample_import(p_user_id text, p_import_key text, p_sample_version text, p_subject text, p_answers jsonb, p_correct integer, p_total integer)
 RETURNS TABLE(created boolean, correct smallint, total smallint, created_at timestamptz)
 LANGUAGE plpgsql SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.sample_imports%rowtype;
begin
  select * into r from public.sample_imports s where s.import_key = p_import_key;
  if found then
    if r.user_id is distinct from p_user_id then raise exception 'import_key_taken'; end if;
    return query select false, r.correct, r.total, r.created_at; return;
  end if;
  insert into public.sample_imports (user_id, import_key, sample_version, subject, answers, correct, total)
  values (p_user_id, p_import_key, p_sample_version, p_subject, p_answers, p_correct, p_total)
  on conflict do nothing returning * into r;
  if found then return query select true, r.correct, r.total, r.created_at; return; end if;
  select * into r from public.sample_imports s where s.user_id = p_user_id and s.sample_version = p_sample_version;
  if not found then
    select * into r from public.sample_imports s where s.import_key = p_import_key;
    if not found then raise exception 'sample_import_not_saved'; end if;
    if r.user_id is distinct from p_user_id then raise exception 'import_key_taken'; end if;
  end if;
  return query select false, r.correct, r.total, r.created_at;
end;
$function$;
