  on public.question_interactions (question_id, user_id)
  where interaction_type = 'report' and coalesce(metadata->>'source','') <> 'ai_key_dispute';

-- 2) Cap student reports at 20 per user per 24 h. The route inserts the interaction BEFORE it holds the question and returns 500 on insert error, so a rejected insert never reaches the hold.
create or replace function public.cap_question_reports() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.interaction_type = 'report' and coalesce(new.metadata->>'source','') <> 'ai_key_dispute' then
    if (select count(*) from public.question_interactions qi
        where qi.user_id = new.user_id and qi.interaction_type = 'report'
          and coalesce(qi.metadata->>'source','') <> 'ai_key_dispute'
          and qi.created_at > now() - interval '24 hours') >= 20 then
      raise exception 'REPORT_LIMIT' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;
