CREATE OR REPLACE FUNCTION public.mm_ai_release_credits(p_operation_key text, p_reason text DEFAULT 'released'::text)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  v_res public.ai_credit_reservations%rowtype;
  v_wallet public.ai_credit_wallets%rowtype;
  v_to_included integer;
  v_to_bonus integer;
  v_balance integer;
begin
  select * into v_res from public.ai_credit_reservations where operation_key = p_operation_key;
  if not found then return jsonb_build_object('ok', false, 'error', 'reservation_not_found'); end if;
  select * into v_wallet from public.ai_credit_wallets where user_id = v_res.user_id for update;
  select * into v_res from public.ai_credit_reservations where operation_key = p_operation_key for update;
  if v_res.state = 'released' then return jsonb_build_object('ok', true, 'idempotent', true, 'state', 'released'); end if;
  if v_res.state = 'committed' then return jsonb_build_object('ok', false, 'error', 'already_committed', 'state', 'committed'); end if;
  if v_wallet.period_start = v_res.period_start then
    v_to_included := v_res.from_included; v_to_bonus := v_res.from_bonus;
  else
    v_to_included := 0; v_to_bonus := v_res.from_bonus;  -- was from_included + from_bonus
  end if;
  update public.ai_credit_wallets
     set included_credits_used = greatest(0, included_credits_used - v_to_included),
         bonus_credits = bonus_credits + v_to_bonus, updated_at = now()
   where user_id = v_res.user_id returning * into v_wallet;
  update public.ai_credit_reservations
     set state = 'released', release_reason = left(coalesce(p_reason, 'released'), 200), updated_at = now()
   where id = v_res.id;
  v_balance := greatest(0, v_wallet.included_monthly_credits - v_wallet.included_credits_used) + v_wallet.bonus_credits;
  insert into public.ai_credit_ledger (user_id, amount, reason, feature, reference, wallet_source, balance_after, idempotency_key, metadata)
  values (v_res.user_id, v_to_included + v_to_bonus, 'ai_release', v_res.action, p_operation_key, 'adjustment', v_balance, 'release:' || p_operation_key,
    jsonb_build_object('kind', 'release', 'includedRestored', v_to_included, 'bonusRestored', v_to_bonus, 'includedExpired', v_res.from_included - v_to_included, 'reason', left(coalesce(p_reason, 'released'), 200)));
  return jsonb_build_object('ok', true, 'state', 'released', 'restored', v_to_included + v_to_bonus, 'balance', v_balance);
end;
$function$;
