-- Same function, plus a database-side refusal to approve disputed questions. CREATE OR REPLACE keeps the existing ACL (postgres and service_role).
create or replace function public.moderate_question_with_credit(p_question_id text, p_action text)
returns jsonb language plpgsql set search_path to 'public', 'pg_temp' as $function$
declare v_question public.questions%rowtype; v_credit_user_id text;
begin
  if p_question_id is null or p_action not in ('approve','reject') then raise exception 'invalid moderation parameters'; end if;
  select * into v_question from public.questions where id = p_question_id for update;
  if not found or v_question.status <> 'pending' then return null; end if;
  if p_action = 'approve' and (v_question.verification_state = 'disputed'
     or exists (select 1 from public.question_content_disputes d where d.question_id = p_question_id and d.state = 'open')) then
    raise exception 'automated_evidence_required';
  end if;
  if p_action = 'approve' then
    update public.questions set status='live', verification_state='verified', exploration_state='active', live_at=now() where id=p_question_id returning * into v_question;
    v_credit_user_id := coalesce(v_question.author_id, v_question.uploaded_by);
    if v_credit_user_id is not null then perform public.grant_contribution_credits(v_credit_user_id, 'contribute', 'contribute:' || p_question_id); end if;
  else
    update public.questions set status='rejected', verification_state='rejected', exploration_state='rejected' where id=p_question_id returning * into v_question;
  end if;
  update public.moderation_jobs set status='completed', completed_at=now() where question_id=p_question_id and status in ('queued','processing','retrying');
  return to_jsonb(v_question);
end;
$function$;

